def execute_concurrently_on_shards(nr_shards, operation):
    from concurrent.futures import ThreadPoolExecutor, as_completed, Future
    import threading

    if nr_shards <= 0:
        f = Future()
        f.set_result(None)
        return f

    executor = ThreadPoolExecutor(max_workers=nr_shards)
    shard_futures = [executor.submit(operation, shard_id) for shard_id in range(nr_shards)]

    done = Future()

    def _wait_all():
        try:
            for _f in as_completed(shard_futures):
                _f.result()  # propagate exception if any
            done.set_result(None)
        except BaseException as e:
            done.set_exception(e)

    waiter = threading.Thread(target=_wait_all, daemon=True)
    waiter.start()
    return done

