def uninstall_package_at_path(base_path: str, package_spec: str, binaries: List[str], ctx: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """
    Uninstall a package and given binaries from base_path using installation tracking information.

    Returns a dict with keys:
      - success: bool
      - message: str (optional)
      - removed_package_id: Any (optional)
      - removed_binaries: List[str] (optional)
      - path: str (optional) - path to tracking file used
      - errors: List[str] (optional)
    """
    import json, os
    errors: List[str] = []

    # Optional logging through provided context
    if isinstance(ctx, dict) and callable(ctx.get("log", None)):
        try:
            ctx["log"](f"Uninstall requested: spec={package_spec}, binaries={binaries}, base_path={base_path}")
        except Exception:
            pass

    # Locate installation tracking file
    tracking_candidates = ["install_manifest.json", "installed_packages.json", "packages.json"]
    track_path = None
    for cand in tracking_candidates:
        path = os.path.join(base_path, cand)
        if os.path.exists(path):
            track_path = path
            break
    if track_path is None:
        return {"success": False, "message": "No installation tracking file found in path", "path": base_path}

    # Load tracking information
    try:
        with open(track_path, "r") as f:
            tracking = json.load(f)
    except Exception as e:
        return {"success": False, "message": f"Failed to load tracking file: {e}", "path": track_path}

    packages = tracking.get("packages", [])
    pkg_id = None
    for p in packages:
        if (p.get("spec") == package_spec) or (p.get("name") == package_spec) or (str(p.get("id")) == str(package_spec)):
            pkg_id = p.get("id")
            break
    if pkg_id is None:
        return {"success": False, "message": "Package spec not found in tracking information", "spec": package_spec, "packages_count": len(packages)}

    # Uninstall binaries for this package
    to_remove = set(binaries) if binaries else set()
    removed_binaries: List[str] = []
    for p in packages:
        if p.get("id") == pkg_id:
            for b in p.get("binaries", []):
                if not to_remove or (b in to_remove):
                    bin_path = os.path.join(base_path, "bin", b)
                    try:
                        if os.path.exists(bin_path):
                            os.remove(bin_path)
                    except Exception as e:
                        errors.append(f"Failed to remove binary {b}: {e}")
                    else:
                        removed_binaries.append(b)
            break

    # Remove package from tracking
    tracking["packages"] = [pp for pp in packages if pp.get("id") != pkg_id]
    if "binaries" in tracking:
        tracking["binaries"] = [bb for bb in tracking.get("binaries", []) if bb not in removed_binaries]

    # Persist tracking changes
    try:
        with open(track_path, "w") as f:
            json.dump(tracking, f, indent=2)
    except Exception as e:
        return {"success": False, "message": f"Failed to write tracking file: {e}", "path": track_path, "removed_binaries": removed_binaries, "errors": errors}

    result = {"success": True, "removed_package_id": pkg_id, "removed_binaries": removed_binaries, "path": track_path}
    if errors:
        result["errors"] = errors
    return result

