def files_identical(path1, path2):
    """Return True if two files are identical, resolving symbolic links first.

    Procedure:
    1) Resolve both input paths to their real paths.
    2) If the resolved paths are identical, return True.
    3) If both file sizes can be obtained and differ, return False.
    4) Otherwise, compare file contents in large chunks to confirm equality.
    """
    import os

    def _safe_realpath(p):
        try:
            return os.path.realpath(p)
        except Exception:
            return p

    r1 = _safe_realpath(path1)
    r2 = _safe_realpath(path2)

    if r1 == r2:
        return True

    try:
        size1 = os.path.getsize(path1)
        size2 = os.path.getsize(path2)
    except OSError:
        size1 = size2 = None

    if (size1 is not None) and (size2 is not None) and (size1 != size2):
        return False

    try:
        with open(path1, 'rb') as f1, open(path2, 'rb') as f2:
            chunk = 1024 * 1024
            while True:
                b1 = f1.read(chunk)
                b2 = f2.read(chunk)
                if b1 != b2:
                    return False
                if not b1:
                    return True
    except OSError:
        return False

