""from typing import Callable, Type, Any
import functools

def wrap_api_method_for_raw_response(api_method: Callable, response_class: Type[Any]) -> Callable:
    \"\"\"
    Wraps an API method so that it returns an instance of `response_class` when possible.
    It injects headers to request raw data and indicate the desired response class.
    \"\"\"
    @functools.wraps(api_method)
    def wrapper(*args, **kwargs):
        # Normalize headers
        headers = kwargs.pop('headers', {}) or {}
        if not isinstance(headers, dict):
            headers = dict(headers)
        headers = dict(headers)  # make a shallow copy to avoid mutating caller's dict

        # Inject headers to request raw data and target class
        headers.setdefault('Accept', 'application/octet-stream')
        headers['X-Return-Raw-Data'] = 'true'
        headers['X-Response-Class'] = f\"{response_class.__module__}.{response_class.__name__}\"
        kwargs['headers'] = headers

        # Call the original API method
        result = api_method(*args, **kwargs)

        # If already the desired type, return as-is
        if isinstance(result, response_class):
            return result

        # Attempt to cast/construct the response_class from the returned data
        try:
            # If raw bytes, try a common factory
            if isinstance(result, (bytes, bytearray)):
                if hasattr(response_class, 'from_raw'):
                    return response_class.from_raw(bytes(result))
                # Fallback to direct constructor with bytes
                try:
                    return response_class(bytes(result))
                except Exception:
                    pass

            # If a dict, try a dict-based constructor
            if isinstance(result, dict) and hasattr(response_class, 'from_dict'):
                return response_class.from_dict(result)

        except Exception:
            # If casting fails for any reason, fall back to the raw result
            pass

        return result

    return wrapper
