use serde_json;

// Represents a single language server's configuration
#[derive(Debug)]
pub struct LanguageServerConfiguration {
    pub name: String,
    pub enabled: Vec<String>,
    pub excluded: Vec<String>,
}

// Serialize configurations into the described JSON format
pub fn serialize_language_server_configurations(
    configs: &[LanguageServerConfiguration],
) -> serde_json::Result<String> {
    // Build a JSON array where each item is either:
    // - a string with just the name, if no features are specified
    // - an object with name, enabled, and excluded, otherwise
    let mut items = Vec::with_capacity(configs.len());

    for cfg in configs {
        if cfg.enabled.is_empty() && cfg.excluded.is_empty() {
            items.push(serde_json::Value::String(cfg.name.clone()));
        } else {
            let mut obj = serde_json::Map::new();
            obj.insert("name".to_string(), serde_json::Value::String(cfg.name.clone()));
            obj.insert("enabled".to_string(), serde_json::to_value(&cfg.enabled).unwrap_or_default());
            obj.insert("excluded".to_string(), serde_json::to_value(&cfg.excluded).unwrap_or_default());
            items.push(serde_json::Value::Object(obj));
        }
    }

    serde_json::to_string(&items)
}

