import uuid

class EventHandler:
    def __init__(self, func, stop_propagation=False, prevent_default=False, id=None):
        """
        Create an event handler that wraps a user-defined function.

        - func: the user-defined function to execute when the handler is called.
        - stop_propagation: if True, attempt to stop event propagation via event.stopPropagation / event.stop_propagate.
        - prevent_default: if True, attempt to call event.preventDefault / event.prevent_default.
        - id: optional unique identifier; if not provided, a UUID v4 is generated.
        """
        self.func = func
        self.stop_propagation = bool(stop_propagation)
        self.prevent_default = bool(prevent_default)
        self.id = id or str(uuid.uuid4())

    def __call__(self, event, *args, **kwargs):
        # Apply preventDefault if requested
        if self.prevent_default:
            if hasattr(event, "preventDefault"):
                try:
                    event.preventDefault()
                except Exception:
                    pass
            elif hasattr(event, "prevent_default"):
                try:
                    event.prevent_default()
                except Exception:
                    pass

        # Apply stopPropagation if requested
        if self.stop_propagation:
            if hasattr(event, "stopPropagation"):
                try:
                    event.stopPropagation()
                except Exception:
                    pass
            elif hasattr(event, "stop_propagate"):
                try:
                    event.stop_propagate()
                except Exception:
                    pass

        return self.func(event, *args, **kwargs)

    def __repr__(self):
