pub fn uninstall_by_tracking_path<P: AsRef<std::path::Path>>(
    install_path: P,
    spec: &str,
    binaries: &[String],
    gctx: &GlobalContext,
) -> CargoResult<()> {
    // Path to the installation tracking information
    let tracking_path = install_path.as_ref().join("install-tracking.json");

    // 1) Load the installation tracking information from the specified path
    let mut tracking = InstallTracking::load(&tracking_path)
        .map_err(|e| CargoError::msg(format!("Failed to load install tracking: {}", e)))?;

    // 2) Retrieve the list of installed packages from tracking
    // (Assumed to exist as part of InstallTracking)

    // 3) Identify the package ID based on the provided specification string
    let pkg_id = tracking
        .find_package_id_by_spec(spec)
        .ok_or_else(|| CargoError::msg(format!("No installed package matches spec '{}'", spec)))?;

    // 4) Proceed to uninstall the identified package and specified binaries
    //    using the loaded tracking information
    tracking
        .uninstall_package(&pkg_id, binaries, gctx)
        .map_err(|e| CargoError::msg(format!("Uninstall failed: {}", e)))?;

    // 5) Persist updated tracking information back to disk
    tracking
        .save(&tracking_path)
        .map_err(|e| CargoError::msg(format!("Failed to save tracking: {}", e)))?;

    Ok(())
}

