class Solution:
    def sortVowels(self, s: str) -> str:
        # Helper to check if a character is a vowel (case-insensitive)
        def is_vowel(ch: str) -> bool:
            return ch.lower() in {'a', 'e', 'i', 'o', 'u'}

        vowel_positions = []
        vowels = []

        for i, ch in enumerate(s):
            if is_vowel(ch):
                vowel_positions.append(i)
                vowels.append(ch)

        if not vowels:
            return s  # No vowels to sort

        vowels.sort()  # Sort vowels by ASCII value (upper-case before lower-case)

        s_list = list(s)
        for idx, pos in enumerate(vowel_positions):
            s_list[pos] = vowels[idx]

        return ''.join(s_list)
