    (0,3,6), (1,4,7), (2,5,8),   # cols
    (0,4,8), (2,4,6)             # diagonals
]

def line_winner(board):
    # board: tuple of 9 values in {0,1,2}, where 1=red(Takahashi), 2=blue(Aoki)
    for a,b,c in LINES:
        va, vb, vc = board[a], board[b], board[c]
        if va != 0 and va == vb == vc:
            return va
    return 0

# Minimax with memoization on (board, D, turn)
# D = current red_score - blue_score
# turn: 0 for Takahashi (red to move), 1 for Aoki (blue to move)
@lru_cache(maxsize=None)
def dfs(board, D, turn):
    w = line_winner(board)
    if w == 1:
        return 1
    if w == 2:
        return -1

    # Available moves
    zeros = [i for i, v in enumerate(board) if v == 0]
    if not zeros:
        # Full board: winner by score difference
        return 1 if D > 0 else -1

    if turn == 0:  # Takahashi to move (maximize final result)
        best = -2
        for i in zeros:
            new_board = list(board)
            new_board[i] = 1  # red moves
            new_board_t = tuple(new_board)
            new_D = D + A_tuple[i]

            w2 = line_winner(new_board_t)
            if w2 == 1:
                val = 1
            elif w2 == 2:
                val = -1
            else:
                if all(v != 0 for v in new_board_t):
                    val = 1 if new_D > 0 else -1
                else:
                    val = dfs(new_board_t, new_D, 1)

            if val > best:
                best = val
                if best == 1:
                    return 1
        return best
    else:  # Aoki to move (minimize final result)
        best = 2
        for i in zeros:
            new_board = list(board)
            new_board[i] = 2  # blue moves
            new_board_t = tuple(new_board)
            new_D = D - A_tuple[i]

            w2 = line_winner(new_board_t)
            if w2 == 1:
                val = 1
            elif w2 == 2:
                val = -1
            else:
                if all(v != 0 for v in new_board_t):
                    val = 1 if new_D > 0 else -1
                else:
                    val = dfs(new_board_t, new_D, 0)

            if val < best:
                best = val
                if best == -1:
                    return -1
        return best

