from typing import List

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n <= 1:
            return True

        maxv = max(nums)
        if maxv <= 1:
            # All numbers are 1; no edges exist between distinct indices
            return n == 1

        # Sieve for smallest prime factor up to max(nums)
        spf = list(range(maxv + 1))
        limit = int(maxv ** 0.5) + 1
        for i in range(2, limit):
            if spf[i] == i:  # i is prime
                for j in range(i * i, maxv + 1, i):
                    if spf[j] == j:
                        spf[j] = i

        def factors(x: int):
            """Return distinct prime factors of x using spf."""
            facs = set()
            while x > 1:
                p = spf[x]
                facs.add(p)
                while x % p == 0:
                    x //= p
            return facs

        # Disjoint Set Union (Union-Find) over indices
        parent = list(range(n))
        rank = [0] * n

        def find(a: int) -> int:
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a: int, b: int):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        # Map prime -> an index that contains this prime; union indices sharing a prime
        prime_to_index = {}
        for i, val in enumerate(nums):
            if val == 1:
                continue
            for p in factors(val):
                if p not in prime_to_index:
                    prime_to_index[p] = i
                else:
                    union(i, prime_to_index[p])

        # Check if all indices are in the same connected component
        root0 = find(0)
        for i in range(1, n):
            if find(i) != root0:
                return False
        return True
