                cand = (cum + v) - min_pref[t1]  # P[j] + nums[j] - P[i]
                if ans is None or cand > ans:
                    ans = cand

            t2 = v + k
            if t2 in min_pref:
                cand = (cum + v) - min_pref[t2]
                if ans is None or cand > ans:
                    ans = cand

            # Update min_pref with current i = j (P[i] = cum)
            if v in min_pref:
                if cum < min_pref[v]:
                    min_pref[v] = cum
            else:
                min_pref[v] = cum

