class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        # Generate all i^x <= n
        powers = []
        i = 1
        while True:
            w = i ** x
            if w > n:
                break
            powers.append(w)
            i += 1

        # 0/1 knapsack: count subsets with sum exactly n
        dp = [0] * (n + 1)
        dp[0] = 1

        for w in powers:
            for s in range(n, w - 1, -1):
                dp[s] = (dp[s] + dp[s - w]) % MOD

