import math

def kth_exclusive(N: int, M: int, K: int) -> int:
    g = math.gcd(N, M)
    lcm = N // g * M  # lcm of N and M
    def count(x: int) -> int:
        # numbers <= x divisible by exactly one of N or M
        return x // N + x // M - 2 * (x // lcm)

    lo, hi = 1, max(N, M) * K * 2  # safe upper bound
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= K:
            hi = mid
        else:
            lo = mid + 1
    return lo

