            # dp0 = min cost up to i with S_i = 0
            # dp1 = min cost up to i with S_i = 1
            dp0 = n * (0 ^ d[0])
            dp1 = n * (1 ^ d[0])

            # Iterate i from 0 to n-2, transitioning to S_{i+1}
            for i in range(n - 1):
                delta = d[i + 1] ^ d[i]  # delta_{i+1} = d_{i+1} XOR d_i
                ndp0, ndp1 = INF, INF

                # Transition from S_i = 0
                cur = dp0
                for s_cur, cur_cost in ((0, dp0), (1, dp1)):
