class Solution:
    def punishmentNumber(self, n: int) -> int:
        # Helper to check if the decimal string of i*i can be partitioned into
        # substrings whose integer values sum to i.
        def can_partition(s: str, target: int) -> bool:
            m = len(s)
            if m == 0:
                return False

            # Precompute values of all substrings s[a:b] as integers.
            # vals[a][b] stores int(s[a:b]) for 0 <= a < b <= m
            vals = [[0] * (m + 1) for _ in range(m)]
            for a in range(m):
                v = 0
                for b in range(a + 1, m + 1):
                    v = v * 10 + (ord(s[b - 1]) - 48)
                    vals[a][b] = v

            # DP using reachability sets: reach[pos] contains all possible sums
            # achievable by partitioning s[:pos].
            reach = [set() for _ in range(m + 1)]
            reach[0].add(0)

            for pos in range(m):
                if not reach[pos]:
                    continue
                for acc in list(reach[pos]):
                    for end in range(pos + 1, m + 1):
                        ns = acc + vals[pos][end]
                        if ns <= target:
                            reach[end].add(ns)

            return target in reach[m]

        total = 0
        for i in range(1, n + 1):
            sq = i * i
            if can_partition(str(sq), i):
                total += sq
        return total


